import {validateSkillProject,SkillPlayer} from '../effects/runtime.mjs';
export function mountMapSkillFX(h){
 const $=id=>document.getElementById(id),panel=document.createElement('section');panel.dataset.panel='skillfx';panel.id='mapSkillFX';panel.innerHTML='<h2>Skill & VFX trên map</h2><a href="../effects/index.html" target="_blank" rel="noopener">✧ Mở Studio thiết kế Skill & VFX ↗</a><p class="hint">Tạo/ghép timeline trong mục riêng, xuất skill-pack rồi nhập ở đây. Chỉ thử hình ảnh, không trừ SP hay gây sát thương quái.</p><button id="importSkills">Nhập skill-pack / project</button><input id="skillPackFile" type="file" accept=".json" hidden><button id="removeSkills">Gỡ gói skill khỏi map</button><label>Skill đang thử<select id="mapSkillList"></select></label><div class="pair"><label>Hướng (độ)<input id="skillAim" type="number" value="0"></label><label>Cách người phát<input id="skillDistance" type="number" min="0" max="4096" value="180"></label></div><button id="castMapSkill" class="primary" disabled>✧ Dùng thử skill</button><p id="mapSkillInfo" class="hint" role="status"></p><p class="hint">Có thể dùng thử khi đứng yên hoặc Chạy thử để skill theo người di chuyển. Gói được lưu chung nguyên map. Game mới phải tích hợp skill-runtime.mjs, không tự có luật chiến đấu.</p>';
 document.querySelector('aside.right').append(panel);const menu=document.createElement('button');menu.dataset.tab='skillfx';menu.textContent='✧ Skill & VFX';$('mapMenu').querySelector('nav').append(menu);
 let project=null,player=null,images=new Map(),sequence=0,loading=false;const on=(id,fn)=>$(id).addEventListener('click',h.safe(fn));
 on('importSkills',()=>$('skillPackFile').click());$('skillPackFile').addEventListener('change',h.safe(async()=>{const f=$('skillPackFile').files[0];if(!f)return;try{if(f.size>40*1024*1024)throw Error('Gói skill tối đa 40 MB');const pack=structuredClone(validateSkillProject(JSON.parse(await f.text())));h.stop();h.update(p=>p.skillPack=pack);h.message('Đã nhập '+Object.keys(pack.skills).length+' skill · gói đi cùng nguyên map.')}finally{$('skillPackFile').value=''}}));
 on('removeSkills',()=>{h.stop();h.update(p=>delete p.skillPack);h.message('Đã gỡ gói skill khỏi map. Có thể Hoàn tác.')});
 on('castMapSkill',()=>{if(!player||loading)throw Error('Chờ tải ảnh skill');const a=h.state.playing?h.state.actor:h.state.project.spawn,angle=Number($('skillAim').value)*Math.PI/180,d=Number($('skillDistance').value);if(!Number.isFinite(angle)||!Number.isFinite(d)||d<0||d>4096)throw Error('Hướng/khoảng cách không hợp lệ');const id=$('mapSkillList').value,result=player.cast(id,{caster:a,target:{x:a.x+Math.cos(angle)*d,y:a.y+Math.sin(angle)*d}});h.message(result?'Đang thử '+id+' · chỉ VFX, không tác động quái.':'Skill bị động hoặc đang hồi chiêu.')});
 async function reload(p){const token=++sequence;player=null;images=new Map();const old=$('mapSkillList').value;$('mapSkillList').replaceChildren(...Object.values(p.skillPack?.skills||{}).map(s=>new Option(s.name+' · '+s.id,s.id)));if(p.skillPack?.skills[old])$('mapSkillList').value=old;$('removeSkills').disabled=!p.skillPack;$('castMapSkill').disabled=true;if(!p.skillPack){$('mapSkillInfo').textContent='Chưa có gói skill. Map cũ giữ nguyên dữ liệu.';return}loading=true;try{validateSkillProject(p.skillPack);const pairs=await Promise.all([...new Set(Object.values(p.skillPack.effects).flatMap(e=>(e.frames||[]).map(f=>f.src)))].map(async src=>[src,await h.image(src)]));if(token!==sequence)return;images=new Map(pairs);player=new SkillPlayer(p.skillPack,{onEvent:e=>{if(e.type==='hit-marker')h.message('Mốc hit '+e.skillId+' · tín hiệu hình ảnh, không gây sát thương.')}});$('mapSkillInfo').textContent=Object.keys(p.skillPack.skills).length+' skill đã nạp · '+Object.keys(p.skillPack.effects).length+' VFX · metadata clip/hit dành cho game.'}catch(e){h.message(e.message);$('mapSkillInfo').textContent=e.message}finally{if(token===sequence){loading=false;$('castMapSkill').disabled=!player}}}
 return {tick(dt){if(project!==h.state.project){project=h.state.project;void reload(project)}player?.update(dt)},draw(ctx,layer){player?.draw(ctx,images,{layer})},clear(){player?.clear()}};
}
